CREATE TABLE areas (pincode varchar(6) PRIMARY KEY CHECK(pincode ~ '^[0-9]{6}$'), locality text NOT NULL, city text NOT NULL, lat numeric(8,4) NOT NULL CHECK(lat BETWEEN -90 AND 90), lng numeric(8,4) NOT NULL CHECK(lng BETWEEN -180 AND 180));
CREATE TABLE scam_types (value text PRIMARY KEY);
CREATE TABLE channels (value text PRIMARY KEY);
CREATE TABLE identifiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identifier_type text NOT NULL CHECK(identifier_type IN ('phone','upi','url','sender_id')), normalized_value text NOT NULL CHECK(length(normalized_value)>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX identifiers_type_value_uq ON identifiers(identifier_type,normalized_value);
CREATE TABLE cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identifier_id uuid NOT NULL UNIQUE REFERENCES identifiers(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reporter_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_hmac varchar(64) NOT NULL UNIQUE CHECK(reporter_hmac ~ '^[0-9a-f]{64}$'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id text NOT NULL UNIQUE, case_id uuid NOT NULL REFERENCES cases(id), reporter_signal_id uuid NOT NULL REFERENCES reporter_signals(id), ip_prefix_hmac varchar(64) NOT NULL CHECK(ip_prefix_hmac ~ '^[0-9a-f]{64}$'), occurred_at timestamptz NOT NULL, reported_at timestamptz NOT NULL CHECK(reported_at >= occurred_at), pincode varchar(6) NOT NULL REFERENCES areas(pincode), scam_type text NOT NULL REFERENCES scam_types(value), channel text NOT NULL REFERENCES channels(value), sanitized_note text NOT NULL DEFAULT '', has_screenshot boolean NOT NULL DEFAULT false, amount_lost_inr numeric(16,2) NOT NULL DEFAULT 0 CHECK(amount_lost_inr>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trust_decisions (report_id uuid PRIMARY KEY REFERENCES reports(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','eligible','ignored')), weight numeric(8,4) CHECK(weight BETWEEN 0 AND 1), reason_code text, algorithm_version text, decided_at timestamptz, CHECK((status='pending' AND decided_at IS NULL) OR (status<>'pending' AND decided_at IS NOT NULL)));
CREATE TABLE case_statistics (case_id uuid PRIMARY KEY REFERENCES cases(id) ON DELETE CASCADE, raw_report_count integer NOT NULL DEFAULT 0 CHECK(raw_report_count>=0), distinct_reporter_count integer NOT NULL DEFAULT 0 CHECK(distinct_reporter_count BETWEEN 0 AND raw_report_count), independent_trusted_reporter_count integer NOT NULL DEFAULT 0 CHECK(independent_trusted_reporter_count BETWEEN 0 AND distinct_reporter_count), eligible_report_count integer NOT NULL DEFAULT 0 CHECK(eligible_report_count BETWEEN 0 AND raw_report_count), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE area_statistics (pincode varchar(6) NOT NULL REFERENCES areas(pincode), day date NOT NULL, scam_type text NOT NULL REFERENCES scam_types(value), eligible_report_count integer NOT NULL DEFAULT 0 CHECK(eligible_report_count>=0), PRIMARY KEY(pincode,day,scam_type));
CREATE TABLE verified_identifiers (identifier_id uuid PRIMARY KEY REFERENCES identifiers(id), label text NOT NULL);
CREATE TABLE challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identifier_id uuid NOT NULL REFERENCES identifiers(id), status text NOT NULL DEFAULT 'under_review' CHECK(status IN ('under_review','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE SCHEMA restricted;
REVOKE ALL ON SCHEMA restricted FROM PUBLIC;
CREATE TABLE restricted.challenge_contacts (challenge_id uuid PRIMARY KEY REFERENCES public.challenges(id) ON DELETE CASCADE, claimant_name text NOT NULL, contact_email text NOT NULL, proof_note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON restricted.challenge_contacts FROM PUBLIC;
CREATE TABLE license_state (id integer PRIMARY KEY CHECK(id=1), licensee text NOT NULL, expires_at timestamptz NOT NULL, signature text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE latest_seen_time (id integer PRIMARY KEY CHECK(id=1), latest_seen_at timestamptz NOT NULL);
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pincode varchar(6) NOT NULL REFERENCES areas(pincode), type text NOT NULL CHECK(type IN ('SPIKE','NEW_TYPE')), scam_type text REFERENCES scam_types(value), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL CHECK(window_end>window_start), eligible_count integer NOT NULL CHECK(eligible_count>=0), baseline_per_day numeric CHECK(baseline_per_day>=0));
CREATE UNIQUE INDEX alerts_window_uq ON alerts(pincode,type,coalesce(scam_type,''),window_start,window_end);
CREATE INDEX reports_case_time_idx ON reports(case_id,occurred_at);
CREATE INDEX reports_area_time_idx ON reports(pincode,occurred_at);
CREATE INDEX reports_area_type_time_idx ON reports(pincode,scam_type,occurred_at);
CREATE INDEX reports_reporter_time_idx ON reports(reporter_signal_id,occurred_at);
CREATE INDEX reports_network_time_idx ON reports(ip_prefix_hmac,occurred_at);
CREATE INDEX decisions_eligible_idx ON trust_decisions(report_id) WHERE status='eligible';
CREATE INDEX challenges_identifier_idx ON challenges(identifier_id,status);
CREATE UNIQUE INDEX challenges_under_review_uq ON challenges(identifier_id) WHERE status='under_review';
CREATE INDEX alerts_area_time_idx ON alerts(pincode,window_end);
